-- Publishes the final robust-Z season-award formulas without mutating v1.
BEGIN;

UPDATE season_award_formula
SET status = 'retired'
WHERE status = 'active' AND version = 1
  AND award_code IN ('PLAYER_OF_SEASON','DEFENDER_OF_SEASON','GOALKEEPER_OF_SEASON',
                     'YOUNG_PLAYER_OF_SEASON','IMPACT_SUBSTITUTE_OF_SEASON','MOST_IMPROVED_PLAYER');

     $formula${"award":{"aggregation":"weighted_standardized_components","code":"PLAYER_OF_SEASON","components":[{"code":"reliable_quality","direction":"higher","metric":"Q * minutes/(minutes+900)","weight":0.8},{"code":"season_volume","direction":"higher","metric":"sqrt(minutes/maximum player minutes)","weight":0.2}],"eligibility":{"final":"same calculation over all 22 rounds","provisional":"one finished appearance; reliability controls the round-four sample","resolved_position_required":true},"final_formula":"JTS = 0.80*(Q*R) + 0.20*V","id":"20000000-0000-4000-8000-000000000001","name":"Jugador de la temporada","status":"active","tie_breakers":["higher raw JTS","higher total minutes","player UUID ascending"],"version":2},"catalog_version":2,"common_metrics":{"position_weights":"GK=(.05,.10,.10,.30,.45); DEF=(.10,.20,.35,.20,.15); MID=(.15,.30,.15,.20,.20); FWD=(.35,.20,.05,.15,.25) for (A,P,D,C,I)","public_scale":"the raw standardized award score determines ranking; 100/(1+exp(-raw_score)) is used only to display it on a 0-100 scale","quality":"Q = w_A*A + w_P*P + w_D*D + w_C*C + w_I*I; A, P, D, C and I are positional robust Z-scores","reliability":"R = minutes / (minutes + 900)","season_volume":"V = sqrt(minutes / maximum player minutes in the edition cohort)"},"normalization":{"cohort":"players in the same edition, position and calculation window","fallback":"use positional standard Z-score when MAD is zero; use 0 when the cohort has no dispersion","formula":"(x - median(position, metric)) / (1.4826 * MAD(position, metric))","method":"positional_robust_z_score","missing_data":"a required unavailable metric makes the player ineligible; zero is used only when the provider semantics establish that an omitted count means no actions","rate_adjustment":"shrink rates toward the positional cohort rate with metric-specific pseudo-attempts before standardization"},"specification":"go-football/season-awards","status":"active"}$formula$::jsonb, now());

     $formula${"award":{"aggregation":"weighted_standardized_components","code":"DEFENDER_OF_SEASON","components":[{"code":"reliable_defence","direction":"higher","metric":"DEF * minutes/(minutes+900); DEF=.20*Z(duel win rate)+.15*Z(aerial win rate)+.20*Z(interceptions/90)+.15*Z(tackles/90)+.10*Z(blocks/90)+.10*Z(recoveries/90)+.10*Z(progression/90)-.10*Z(errors/90)","weight":0.85},{"code":"season_volume","direction":"higher","metric":"sqrt(minutes/maximum defender minutes)","weight":0.15}],"eligibility":{"position":"DEF","provisional":"one finished appearance"},"final_formula":"DTS = 0.85*(DEF*R) + 0.15*V","id":"20000000-0000-4000-8000-000000000002","name":"Defensa de la temporada","status":"active","tie_breakers":["higher raw DTS","higher total minutes","player UUID ascending"],"version":2},"catalog_version":2,"common_metrics":{"position_weights":"GK=(.05,.10,.10,.30,.45); DEF=(.10,.20,.35,.20,.15); MID=(.15,.30,.15,.20,.20); FWD=(.35,.20,.05,.15,.25) for (A,P,D,C,I)","public_scale":"the raw standardized award score determines ranking; 100/(1+exp(-raw_score)) is used only to display it on a 0-100 scale","quality":"Q = w_A*A + w_P*P + w_D*D + w_C*C + w_I*I; A, P, D, C and I are positional robust Z-scores","reliability":"R = minutes / (minutes + 900)","season_volume":"V = sqrt(minutes / maximum player minutes in the edition cohort)"},"normalization":{"cohort":"players in the same edition, position and calculation window","fallback":"use positional standard Z-score when MAD is zero; use 0 when the cohort has no dispersion","formula":"(x - median(position, metric)) / (1.4826 * MAD(position, metric))","method":"positional_robust_z_score","missing_data":"a required unavailable metric makes the player ineligible; zero is used only when the provider semantics establish that an omitted count means no actions","rate_adjustment":"shrink rates toward the positional cohort rate with metric-specific pseudo-attempts before standardization"},"specification":"go-football/season-awards","status":"active"}$formula$::jsonb, now());

     $formula${"award":{"aggregation":"weighted_standardized_components","code":"GOALKEEPER_OF_SEASON","components":[{"code":"reliable_shot_stopping","direction":"higher","metric":"Z(save percentage adjusted for attempts) * SOTFaced/(SOTFaced+100); use Z((PSxG-GA)/SOTFaced) when PSxG is available","weight":0.4},{"code":"distribution","direction":"higher","metric":"Z(attempt-adjusted pass and long-ball accuracy)","weight":0.2},{"code":"cross_control","direction":"higher","metric":"Z((high claims+punches)/90)","weight":0.15},{"code":"sweeping","direction":"higher","metric":"Z(attempt-adjusted keeper-sweeper success rate)","weight":0.1},{"code":"error_avoidance","direction":"higher","metric":"Z(-errors leading to shots or goals per 90)","weight":0.1},{"code":"season_volume","direction":"higher","metric":"sqrt(minutes/maximum goalkeeper minutes)","weight":0.05}],"eligibility":{"minimum_shots_on_target_faced":1,"position":"GK"},"final_formula":"PTS = .40*ShotStop* + .20*Distribution + .15*CrossControl + .10*Sweeping + .10*ErrorAvoidance + .05*V","id":"20000000-0000-4000-8000-000000000003","name":"Portero de la temporada","status":"active","tie_breakers":["higher reliable shot stopping","higher save percentage","higher total minutes","player UUID ascending"],"version":2},"catalog_version":2,"common_metrics":{"position_weights":"GK=(.05,.10,.10,.30,.45); DEF=(.10,.20,.35,.20,.15); MID=(.15,.30,.15,.20,.20); FWD=(.35,.20,.05,.15,.25) for (A,P,D,C,I)","public_scale":"the raw standardized award score determines ranking; 100/(1+exp(-raw_score)) is used only to display it on a 0-100 scale","quality":"Q = w_A*A + w_P*P + w_D*D + w_C*C + w_I*I; A, P, D, C and I are positional robust Z-scores","reliability":"R = minutes / (minutes + 900)","season_volume":"V = sqrt(minutes / maximum player minutes in the edition cohort)"},"normalization":{"cohort":"players in the same edition, position and calculation window","fallback":"use positional standard Z-score when MAD is zero; use 0 when the cohort has no dispersion","formula":"(x - median(position, metric)) / (1.4826 * MAD(position, metric))","method":"positional_robust_z_score","missing_data":"a required unavailable metric makes the player ineligible; zero is used only when the provider semantics establish that an omitted count means no actions","rate_adjustment":"shrink rates toward the positional cohort rate with metric-specific pseudo-attempts before standardization"},"specification":"go-football/season-awards","status":"active"}$formula$::jsonb, now());

     $formula${"award":{"aggregation":"weighted_standardized_components","code":"YOUNG_PLAYER_OF_SEASON","components":[{"code":"reliable_quality","direction":"higher","metric":"the same Q as PLAYER_OF_SEASON * minutes/(minutes+900)","weight":0.8},{"code":"season_volume","direction":"higher","metric":"sqrt(minutes/maximum player minutes), identical to PLAYER_OF_SEASON","weight":0.2}],"eligibility":{"age_rule":"age < 23 on edition.starts_on; date_of_birth is required","resolved_position_required":true},"final_formula":"JJTS = 0.80*(Q*R) + 0.20*V; age < 23; no age bonus","id":"20000000-0000-4000-8000-000000000004","name":"Jugador joven de la temporada (Sub-23)","status":"active","tie_breakers":["higher raw JJTS","higher total minutes","player UUID ascending"],"version":2},"catalog_version":2,"common_metrics":{"position_weights":"GK=(.05,.10,.10,.30,.45); DEF=(.10,.20,.35,.20,.15); MID=(.15,.30,.15,.20,.20); FWD=(.35,.20,.05,.15,.25) for (A,P,D,C,I)","public_scale":"the raw standardized award score determines ranking; 100/(1+exp(-raw_score)) is used only to display it on a 0-100 scale","quality":"Q = w_A*A + w_P*P + w_D*D + w_C*C + w_I*I; A, P, D, C and I are positional robust Z-scores","reliability":"R = minutes / (minutes + 900)","season_volume":"V = sqrt(minutes / maximum player minutes in the edition cohort)"},"normalization":{"cohort":"players in the same edition, position and calculation window","fallback":"use positional standard Z-score when MAD is zero; use 0 when the cohort has no dispersion","formula":"(x - median(position, metric)) / (1.4826 * MAD(position, metric))","method":"positional_robust_z_score","missing_data":"a required unavailable metric makes the player ineligible; zero is used only when the provider semantics establish that an omitted count means no actions","rate_adjustment":"shrink rates toward the positional cohort rate with metric-specific pseudo-attempts before standardization"},"specification":"go-football/season-awards","status":"active"}$formula$::jsonb, now());

     $formula${"award":{"aggregation":"weighted_standardized_components","code":"IMPACT_SUBSTITUTE_OF_SEASON","components":[{"code":"reliable_impact","direction":"higher","metric":"positional Z(sum(ActionValue*Leverage)) * substitute_minutes/(substitute_minutes+450)","weight":0.55},{"code":"reliable_substitute_quality","direction":"higher","metric":"positional Q_sub * substitute_minutes/(substitute_minutes+450)","weight":0.25},{"code":"substitute_volume","direction":"higher","metric":"sqrt(substitute appearances/maximum substitute appearances)","weight":0.2}],"eligibility":{"minimum_substitute_appearances":1,"only_statistics_after_entering_count":true},"final_formula":"SMS = .55*Impact* + .25*Q_sub* + .20*V_sub","id":"20000000-0000-4000-8000-000000000005","name":"Suplente más decisivo de la temporada","status":"active","tie_breakers":["higher raw SMS","higher leverage-weighted impact","more substitute appearances","player UUID ascending"],"version":2},"catalog_version":2,"common_metrics":{"position_weights":"GK=(.05,.10,.10,.30,.45); DEF=(.10,.20,.35,.20,.15); MID=(.15,.30,.15,.20,.20); FWD=(.35,.20,.05,.15,.25) for (A,P,D,C,I)","public_scale":"the raw standardized award score determines ranking; 100/(1+exp(-raw_score)) is used only to display it on a 0-100 scale","quality":"Q = w_A*A + w_P*P + w_D*D + w_C*C + w_I*I; A, P, D, C and I are positional robust Z-scores","reliability":"R = minutes / (minutes + 900)","season_volume":"V = sqrt(minutes / maximum player minutes in the edition cohort)"},"normalization":{"cohort":"players in the same edition, position and calculation window","fallback":"use positional standard Z-score when MAD is zero; use 0 when the cohort has no dispersion","formula":"(x - median(position, metric)) / (1.4826 * MAD(position, metric))","method":"positional_robust_z_score","missing_data":"a required unavailable metric makes the player ineligible; zero is used only when the provider semantics establish that an omitted count means no actions","rate_adjustment":"shrink rates toward the positional cohort rate with metric-specific pseudo-attempts before standardization"},"specification":"go-football/season-awards","status":"active"}$formula$::jsonb, now());

     $formula${"award":{"aggregation":"weighted_standardized_components","code":"MOST_IMPROVED_PLAYER","components":[{"code":"quality_growth","direction":"higher","metric":"Q_new*Min_new/(Min_new+900) - Q_old*Min_old/(Min_old+900)","weight":0.45},{"code":"efficiency_growth","direction":"higher","metric":"Efficiency_new-Efficiency_old; Efficiency=Z(success)-Z(failure)","weight":0.2},{"code":"influence_growth","direction":"higher","metric":"Influence_new-Influence_old","weight":0.2},{"code":"role_growth","direction":"higher","metric":"Z(ln((Min_new+90)/(Min_old+90)))","weight":0.15}],"eligibility":{"total_rounds":22,"windows":"first half (rounds 1-11) versus second half (rounds 12-22); both windows require minutes"},"final_formula":"MPS = .45*DeltaQ + .20*DeltaEfficiency + .20*DeltaInfluence + .15*Z(RoleGrowth)","id":"20000000-0000-4000-8000-000000000006","name":"Jugador con mayor progresión","status":"active","tie_breakers":["higher raw MPS","higher quality growth","more second-half minutes","player UUID ascending"],"version":2},"catalog_version":2,"common_metrics":{"position_weights":"GK=(.05,.10,.10,.30,.45); DEF=(.10,.20,.35,.20,.15); MID=(.15,.30,.15,.20,.20); FWD=(.35,.20,.05,.15,.25) for (A,P,D,C,I)","public_scale":"the raw standardized award score determines ranking; 100/(1+exp(-raw_score)) is used only to display it on a 0-100 scale","quality":"Q = w_A*A + w_P*P + w_D*D + w_C*C + w_I*I; A, P, D, C and I are positional robust Z-scores","reliability":"R = minutes / (minutes + 900)","season_volume":"V = sqrt(minutes / maximum player minutes in the edition cohort)"},"normalization":{"cohort":"players in the same edition, position and calculation window","fallback":"use positional standard Z-score when MAD is zero; use 0 when the cohort has no dispersion","formula":"(x - median(position, metric)) / (1.4826 * MAD(position, metric))","method":"positional_robust_z_score","missing_data":"a required unavailable metric makes the player ineligible; zero is used only when the provider semantics establish that an omitted count means no actions","rate_adjustment":"shrink rates toward the positional cohort rate with metric-specific pseudo-attempts before standardization"},"specification":"go-football/season-awards","status":"active"}$formula$::jsonb, now());

COMMIT;
